const revokeActiveInvites = `-- name: RevokeActiveInvites :execrows
UPDATE core.invites AS i
SET revoked_at = $1, updated_at = $1
WHERE i.stay_id = $2
  AND i.revoked_at IS NULL
  AND i.expires_at > $1
  AND EXISTS (
    SELECT 1
    FROM core.stays AS s
    JOIN core.memberships AS m
      ON m.accommodation_id = s.accommodation_id
    WHERE s.id = i.stay_id
      AND m.oidc_issuer = $3
      AND m.oidc_subject = $4
      AND m.active = true
      AND m.role IN ('operator', 'manager')
  )
`

type RevokeActiveInvitesParams struct {
	RevokedAt   pgtype.Timestamptz `json:"revoked_at"`
	StayID      pgtype.UUID        `json:"stay_id"`
	OidcIssuer  string             `json:"oidc_issuer"`
	OidcSubject string             `json:"oidc_subject"`
}

func (q *Queries) RevokeActiveInvites(ctx context.Context, arg RevokeActiveInvitesParams) (int64, error) {
	result, err := q.db.Exec(ctx, revokeActiveInvites,
		arg.RevokedAt,
		arg.StayID,
		arg.OidcIssuer,
		arg.OidcSubject,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateStay = `-- name: UpdateStay :one
UPDATE core.stays AS s
SET
  planned_arrival_on = CASE
    WHEN $1::boolean THEN $2::date
    ELSE s.planned_arrival_on
  END,
  planned_departure_on = CASE
    WHEN $3::boolean THEN $4::date
    ELSE s.planned_departure_on
  END,
  expected_guest_count = CASE
    WHEN $5::boolean THEN $6::integer
    ELSE s.expected_guest_count
  END,
  updated_at = $7,
  version = s.version + 1
WHERE s.id = $8
  AND s.version = $9
  AND s.status IN ('draft', 'invited', 'pre_registered', 'checked_in')
  AND EXISTS (
    SELECT 1
    FROM core.accommodations AS accommodation
    WHERE accommodation.id = s.accommodation_id
      AND accommodation.status = 'active'
  )
  AND EXISTS (
    SELECT 1
    FROM core.memberships AS m
    WHERE m.accommodation_id = s.accommodation_id
      AND m.oidc_issuer = $10
      AND m.oidc_subject = $11
      AND m.active = true
      AND m.role IN ('operator', 'manager')
  )
RETURNING
  s.id,
  s.accommodation_id,
  s.status,
  s.planned_arrival_on,
  s.planned_departure_on,
  s.expected_guest_count,
  s.checked_in_at,
  s.checked_out_at,
  s.cancelled_at,
  s.no_show_at,
  s.cancellation_reason_code,
  s.no_show_reason_code,
  s.version,
  s.created_at,
  s.updated_at
`

type UpdateStayParams struct {
	SetPlannedArrival     bool               `json:"set_planned_arrival"`
	PlannedArrivalOn      pgtype.Date        `json:"planned_arrival_on"`
	SetPlannedDeparture   bool               `json:"set_planned_departure"`
	PlannedDepartureOn    pgtype.Date        `json:"planned_departure_on"`
	SetExpectedGuestCount bool               `json:"set_expected_guest_count"`
	ExpectedGuestCount    int32              `json:"expected_guest_count"`
	UpdatedAt             pgtype.Timestamptz `json:"updated_at"`
	StayID                pgtype.UUID        `json:"stay_id"`
	ExpectedVersion       int64              `json:"expected_version"`
	OidcIssuer            string             `json:"oidc_issuer"`
	OidcSubject           string             `json:"oidc_subject"`
}

type UpdateStayRow struct {
	ID                     pgtype.UUID        `json:"id"`
	AccommodationID        pgtype.UUID        `json:"accommodation_id"`
	Status                 CoreStayStatus     `json:"status"`
	PlannedArrivalOn       pgtype.Date        `json:"planned_arrival_on"`
	PlannedDepartureOn     pgtype.Date        `json:"planned_departure_on"`
	ExpectedGuestCount     int32              `json:"expected_guest_count"`
	CheckedInAt            pgtype.Timestamptz `json:"checked_in_at"`
	CheckedOutAt           pgtype.Timestamptz `json:"checked_out_at"`
	CancelledAt            pgtype.Timestamptz `json:"cancelled_at"`
	NoShowAt               pgtype.Timestamptz `json:"no_show_at"`
	CancellationReasonCode *string            `json:"cancellation_reason_code"`
	NoShowReasonCode       *string            `json:"no_show_reason_code"`
	Version                int64              `json:"version"`
	CreatedAt              pgtype.Timestamptz `json:"created_at"`
	UpdatedAt              pgtype.Timestamptz `json:"updated_at"`
}

func (q *Queries) UpdateStay(ctx context.Context, arg UpdateStayParams) (UpdateStayRow, error) {
	row := q.db.QueryRow(ctx, updateStay,
		arg.SetPlannedArrival,
		arg.PlannedArrivalOn,
		arg.SetPlannedDeparture,
		arg.PlannedDepartureOn,
		arg.SetExpectedGuestCount,
		arg.ExpectedGuestCount,
		arg.UpdatedAt,
		arg.StayID,
		arg.ExpectedVersion,
		arg.OidcIssuer,
		arg.OidcSubject,
	)
	var i UpdateStayRow
	err := row.Scan(
		&i.ID,
		&i.AccommodationID,
		&i.Status,
		&i.PlannedArrivalOn,
		&i.PlannedDepartureOn,
		&i.ExpectedGuestCount,
		&i.CheckedInAt,
		&i.CheckedOutAt,
		&i.CancelledAt,
		&i.NoShowAt,
		&i.CancellationReasonCode,
		&i.NoShowReasonCode,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
